+import type { Node as PmNode } from "@tiptap/pm/model";
+import type { Occurrence, SectionInfo, Finding, LensId } from "../living-desk-contract";
+
+export interface Block {
+  kind: "paragraph" | "heading" | "quote" | "code" | "other";
+  text: string;
+  pos: number;
+  paragraph: number;
+  section: number;
+  /** Text runs retain document gaps occupied by inline atoms. */
+  runs?: { offset: number; length: number; pos: number }[];
+}
+export interface Segments { blocks: Block[]; sections: SectionInfo[]; plainText: string }
+
+export function posAtOffset(block: Block, offset: number, end = false): number {
+  const runs = block.runs;
+  if (!runs?.length) return block.pos + offset;
+  // At a text/atom boundary, starts belong to the next text and ends to the preceding text.
+  const run = runs.find((r) => offset >= r.offset && (end ? offset <= r.offset + r.length : offset < r.offset + r.length));
+  if (run) return run.pos + offset - run.offset;
+  const last = runs[runs.length - 1];
+  return last.pos + last.length;
+}
+
+export function segmentDocument(doc: PmNode): Segments {
+  const blocks: Block[] = [];
+  const sections: SectionInfo[] = [];
+  let paragraph = 0;
+  doc.descendants((node, pos) => {
+    if (!node.isTextblock) return;
+    const quote = Array.from({ length: doc.resolve(pos).depth + 1 }, (_, i) => doc.resolve(pos).node(i).type.name).includes("blockquote");
+    const kind: Block["kind"] = quote ? "quote" : node.type.name === "codeBlock" ? "code" : node.type.name === "heading" ? "heading" : node.type.name === "paragraph" ? "paragraph" : "other";
+    if (!sections.length || kind === "heading") {
+      if (sections.length) sections[sections.length - 1].to = pos;
+      sections.push({ index: sections.length, title: kind === "heading" ? node.textContent : "Opening", from: pos + 1, to: doc.content.size, words: 0 });
+    }
+    let text = "";
+    const runs: NonNullable<Block["runs"]> = [];
